import{_ as r,a0 as s,w as p,s as u,ao as o,I as t,x as i,a1 as T,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"有哪些不错的命令行HTTP客户端？ | LCTT x X-CMD","titleTemplate":false,"description":"有哪些不错的命令行HTTP客户端？ | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"有哪些不错的命令行HTTP客户端？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"有哪些不错的命令行HTTP客户端？ | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150429 What are good command line HTTP clients","title":"有哪些不错的命令行HTTP客户端？","tag":"201506","desc":""},"relativePath":"201506/20150429 What are good command line HTTP clients.md","filePath":"[post].md"}'),P={name:"201506/20150429 What are good command line HTTP clients.md"};function a(d,l,m,H,g,w){const n=s("Link");return p(),u("div",null,[l[26]||(l[26]=o('<h1 id="有哪些不错的命令行http客户端" tabindex="-1">有哪些不错的命令行HTTP客户端？ <a class="header-anchor" href="#有哪些不错的命令行http客户端" aria-label="Permalink to “有哪些不错的命令行HTTP客户端？”">​</a></h1><p>“整体大于它的各部分之和”，这是引自希腊哲学家和科学家的亚里士多德的名言。这句话特别切中Linux。在我看来，Linux最强大的地方之一就是它的协作性。Linux的实用性并不仅仅源自大量的开源程序（命令行）。相反，其协作性来自于这些程序的综合利用，有时是结合成更大型的应用。</p><p>Unix哲学引发了一场“软件工具”的运动，关注开发简洁，基础，干净，模块化和扩展性好的代码，并可以运用于其他的项目。这种哲学成为了许多的Linux项目的一个重要的元素。</p><p>好的开源开发者写程序为了确保该程序尽可能运行得好，并且同时能与其他程序很好地协作。目标就是使用者拥有一堆方便的工具，每一个力求干好一件事。许多程序能独立工作得很好。</p><p>这篇文章讨论3个开源命令行HTTP客户端。这些客户端可以让你使用命令行从互联网上下载文件。但同时，他们也可以用于许多有意思的地方，如测试，调式和与HTTP服务器或web应用交互。对于HTTP架构师和API设计人员来说，使用命令行操作HTTP是一个值得花时间学习的技能。如果你需要经常使用API，HTTPie和cURL就非常有价值。</p><p>###HTTPie###</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Internet/Screenshot-httpie.png" alt="HTTPie in action"></p><p>HTTPie（发音 aych-tee-tee-pie）是一款开源的命令行HTTP客户端。它是一个命令行界面，便于手工操作的类cURL工具。</p><p>该软件的目标是使得与Web服务器的交互尽可能的人性化。其提供了一个简单的http命令，允许使用简单且自然的语句发送任意的HTTP请求，并显示不同颜色的输出。HTTPie可以用于测试，调试，以及与HTTP服务器的常规交互。</p><h4 id="功能包括" tabindex="-1">功能包括：#### <a class="header-anchor" href="#功能包括" aria-label="Permalink to “功能包括：####”">​</a></h4><ul><li>生动而直观的语法格式</li><li>经过格式化的彩色终端输出</li><li>内建JSON支持</li><li>支持表单和文件上传</li><li>支持HTTPS，代理和认证</li><li>任意数据请求</li><li>自定义请求头</li><li>持久会话</li><li>类Wget的下载</li><li>支持Python 2.6，2.7和3.x</li><li>支持Linux，Mac OS X 和 Windows</li><li>支持插件</li><li>文档</li><li>单元测试覆盖</li></ul><hr>',12)),t("ul",null,[t("li",null,[l[1]||(l[1]=i("网站:",-1)),T(n,{href:"http://httpie.org/"},{default:e(()=>[...l[0]||(l[0]=[i("httpie.org",-1)])]),_:1})]),l[2]||(l[2]=t("li",null,"开发者: Jakub Roztočil",-1)),l[3]||(l[3]=t("li",null,"证书: 开源",-1)),l[4]||(l[4]=t("li",null,"版本号: 0.9.2",-1))]),l[27]||(l[27]=t("p",null,"###cURL###",-1)),l[28]||(l[28]=t("p",null,[t("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Internet/Screenshot-cURL.png",alt:"cURL in action"})],-1)),l[29]||(l[29]=t("p",null,"cURL是一个开源的命令行工具，用于使用URL语句传输数据，支持DICT, FILE, FTP, FTPS, GOPHER, HTTP, HTTPS,IMAP, IMAPS, LDAP, LDAPS, POP3, POP3S, RTMP, RTSP, SCP, SFTP, SMTP, SMTPS, TELNET和TFTP等协议。",-1)),l[30]||(l[30]=t("p",null,"cURL支持SSL证书，HTTP POST，HTTP PUT，FTP上传，基于表单的HTTP上传，代理，缓存，用户名+密码的认证方式(Basic, Digest, NTLM, Negotiate, kerberos...)，文件续传，代理通道和一些其他的有用功能。",-1)),l[31]||(l[31]=t("h4",{id:"功能包括-1",tabindex:"-1"},[i("功能包括：#### "),t("a",{class:"header-anchor",href:"#功能包括-1","aria-label":"Permalink to “功能包括：####”"},"​")],-1)),l[32]||(l[32]=t("ul",null,[t("li",null,"支持配置文件"),t("li",null,"一个单独命令行请求多个URL"),t("li",{"one,":"","two,":"",three:""},"支持匹配： [0-13]，"),t("li",null,"一个命令上传多个文件"),t("li",null,"自定义最大传输速度"),t("li",null,"重定向了标准错误输出"),t("li",null,"支持Metalink")],-1)),l[33]||(l[33]=t("hr",null,null,-1)),t("ul",null,[t("li",null,[l[6]||(l[6]=i("网站: ",-1)),T(n,{href:"http://curl.haxx.se/"},{default:e(()=>[...l[5]||(l[5]=[i("curl.haxx.se",-1)])]),_:1})]),l[7]||(l[7]=t("li",null,"开发者: Daniel Stenberg",-1)),l[8]||(l[8]=t("li",null,"证书: MIT/X derivate license",-1)),l[9]||(l[9]=t("li",null,"版本号: 7.42.0",-1))]),l[34]||(l[34]=o('<p>###Wget###</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-Wget.png" alt="Wget in action"></p><p>Wget是一个从网络服务器获取信息的开源软件。其名字源于World Wide Web 和 get。Wget支持HTTP，HTTPS和FTP协议，同时也可以通过HTTP代理获取信息。</p><p>Wget可以根据HTML页面的链接，创建远程网络站点的本地副本，完全重造源站点的目录结构。这种方式被称作“递归下载”。</p><p>Wget设计上增强了低速或者不稳定的网络连接。</p><p>功能包括：</p><ul><li>使用REST和RANGE恢复中断的下载</li><li>使用文件名通配符，支持递归地对目录镜像</li><li>基于NLS的消息文件支持多语言</li><li>可选的转换下载文档里地绝对链接为相对链接，使得下载文档可以在本地相互链接</li><li>可以在大多数类UNIX操作系统和微软Windows上运行</li><li>支持HTTP代理</li><li>支持HTTP cookie</li><li>支持HTTP持久连接</li><li>无人照管/后台操作</li><li>当对远程镜像时，使用本地文件时间戳来决定是否需要重新下载文档</li></ul><hr>',8)),t("ul",null,[t("li",null,[l[11]||(l[11]=i("站点: ",-1)),T(n,{href:"https://www.gnu.org/software/wget/"},{default:e(()=>[...l[10]||(l[10]=[i("www.gnu.org/software/wget/",-1)])]),_:1})]),l[12]||(l[12]=t("li",null,"开发者: Hrvoje Niksic, Gordon Matzigkeit, Junio Hamano, Dan Harkless, and many others",-1)),l[13]||(l[13]=t("li",null,"证书: GNU GPL v3",-1)),l[14]||(l[14]=t("li",null,"版本号: 1.16.3",-1))]),l[35]||(l[35]=t("hr",null,null,-1)),t("p",null,[l[16]||(l[16]=i("via: ",-1)),T(n,{href:"http://www.linuxlinks.com/article/20150425174537249/HTTPclients.html"},{default:e(()=>[...l[15]||(l[15]=[i("http://www.linuxlinks.com/article/20150425174537249/HTTPclients.html",-1)])]),_:1})]),t("p",null,[l[19]||(l[19]=i("作者：Frazer Kline 译者：",-1)),T(n,{href:"https://github.com/wi-cuckoo"},{default:e(()=>[...l[17]||(l[17]=[i("wi-cuckoo",-1)])]),_:1}),l[20]||(l[20]=i(" 校对：",-1)),T(n,{href:"https://github.com/wxy"},{default:e(()=>[...l[18]||(l[18]=[i("wxy",-1)])]),_:1})]),t("p",null,[l[23]||(l[23]=i("本文由 ",-1)),T(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[21]||(l[21]=[i("LCTT",-1)])]),_:1}),l[24]||(l[24]=i(" 原创翻译，",-1)),T(n,{href:"http://linux.cn/"},{default:e(()=>[...l[22]||(l[22]=[i("Linux中国",-1)])]),_:1}),l[25]||(l[25]=i(" 荣誉推出",-1))])])}const f=r(P,[["render",a]]);export{S as __pageData,f as default};
